import{_ as s,a0 as r,w as p,s as a,I as o,x as e,a1 as n,A as i,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"去中心化的消息应用 Riot 改名为 Element | LCTT x X-CMD","titleTemplate":false,"description":"去中心化的消息应用 Riot 改名为 Element | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"去中心化的消息应用 Riot 改名为 Element | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"去中心化的消息应用 Riot 改名为 Element | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20200717 Decentralized Messaging App Riot Rebrands to Element","title":"去中心化的消息应用 Riot 改名为 Element","tag":"202008","desc":""},"relativePath":"202008/20200717 Decentralized Messaging App Riot Rebrands to Element.md","filePath":"[post].md"}'),d={name:"202008/20200717 Decentralized Messaging App Riot Rebrands to Element.md"};function u(f,t,R,E,g,x){const l=r("Link");return p(),a("div",null,[t[24]||(t[24]=o("h1",{id:"去中心化的消息应用-riot-改名为-element",tabindex:"-1"},[e("去中心化的消息应用 Riot 改名为 Element "),o("a",{class:"header-anchor",href:"#去中心化的消息应用-riot-改名为-element","aria-label":"Permalink to “去中心化的消息应用 Riot 改名为 Element”"},"​")],-1)),t[25]||(t[25]=o("p",null,"Riot 曾经是，现在也是一款基于开源 Matrix 协议的去中心化即时通讯应用。",-1)),o("p",null,[t[1]||(t[1]=e("6 月底，Riot 即时通讯客户端宣布将改名。他们透露，他们的新名字是 ",-1)),n(l,{href:"https://element.io/"},{default:i(()=>[...t[0]||(t[0]=[e("Element",-1)])]),_:1}),t[2]||(t[2]=e("。让我们来看看 Riot 为什么要改名，还有哪些要改。",-1))]),t[26]||(t[26]=o("h3",{id:"为什么从-riot-改名为-element",tabindex:"-1"},[e("为什么从 Riot 改名为 Element？ "),o("a",{class:"header-anchor",href:"#为什么从-riot-改名为-element","aria-label":"Permalink to “为什么从 Riot 改名为 Element？”"},"​")],-1)),t[27]||(t[27]=o("p",null,[o("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/07/riot-to-element.png?ssl=1",alt:""})],-1)),t[28]||(t[28]=o("p",null,"在说到最新的公告之前，我们先来看看他们当初为什么要改名。",-1)),o("p",null,[t[4]||(t[4]=e("根据 6 月 23 日的一篇",-1)),n(l,{href:"https://element.io/blog/the-world-is-changing/"},{default:i(()=>[...t[3]||(t[3]=[e("博客文章",-1)])]),_:1}),t[5]||(t[5]=e("，该组织改名有三个原因。",-1))]),o("p",null,[t[7]||(t[7]=e("首先，他们表示“某大型游戏公司”曾多次阻止他们注册 Riot 和 Riot.im 产品名称的商标。如果要我猜的话，他们可能指的就是这家",-1)),n(l,{href:"https://en.wikipedia.org/wiki/Riot_Games"},{default:i(()=>[...t[6]||(t[6]=[e("“游戏公司”",-1)])]),_:1}),t[8]||(t[8]=e("）。",-1))]),t[29]||(t[29]=m('<p>其次，他们选择 Riot 这个名字的初衷是为了“唤起一些破坏性和活力的东西”。他们担心人们反而认为这个应用是“专注于暴力”。我想，当前的情形下，这个名字并不算好。</p><p>第三，他们希望澄清 Riot 涉及的众多品牌名称所造成的混乱。例如，Riot 是由一家名为 New Vector 的公司创建的，而 Riot 是托管在 Modular 上，Modular 也是 New Vector 的产品。他们希望简化他们的命名系统，以避免混淆潜在客户。当人们寻找消息解决方案时，他们希望他们只需要寻找一个名字：Element。</p><h3 id="元素即一切" tabindex="-1">元素即一切 <a class="header-anchor" href="#元素即一切" aria-label="Permalink to “元素即一切”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/07/element-desktop.jpg?ssl=1" alt=""></p><p>从 7 月 15 日开始，该应用的名称和公司的名称已经改为 Element（元素）。他们的 Matrix 托管服务现在将被称为 Element Matrix Services。他们的公告很好地总结了这一点。</p><blockquote><p>“对于那些第一次发现我们的人来说，Element 是 Matrix 通信网络中的旗舰级安全协作应用。Element 让你拥有自己的端到端加密聊天服务器，同时还能与更广泛的 Matrix 网络中的其他人连接。”</p></blockquote><p>他们之所以选择 Element 这个名字，是因为它“反映了我们在设计 RiotX 时对简单和清晰的强调；这个名字突出了我们一心一意将 Element 打造成可以想象的最优雅和最实用的主流通讯应用的使命”。他们还说，他们想要一个“能唤起数据所有权和自我主权的概念”的名字。他们还认为这是一个很酷的名字。</p><h3 id="除了改个名之外" tabindex="-1">除了改个名之外 <a class="header-anchor" href="#除了改个名之外" aria-label="Permalink to “除了改个名之外”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/07/element-apps.jpg?ssl=1" alt=""></p><p>最近的公告也表明，此举不仅仅是简单的改名。Element 还发布了“新一代安卓版 Matrix 客户端”。该客户端的前身是 RiotX，现在改名为 Element。（还有呢？）它对以前的客户端进行了彻底的重写，现在支持 VoIP 通话和小部件。Element 还将在 iOS 上推出，支持 iOS 13，并提供“全新的推送通知支持”。</p><p>Element Web 客户端也得到了一些关爱，更新了 UI 和新的更容易阅读的字体。他们还“重写了房间列表控件 —— 增加了房间预览（!!）、按字母顺序排列、可调整列表大小、改进的通知用户界面等”。他们还开始努力改进端到端加密。</p><h3 id="最后思考" tabindex="-1">最后思考 <a class="header-anchor" href="#最后思考" aria-label="Permalink to “最后思考”">​</a></h3><p>Element 公司的人迈出了一大步，做出了这样的重大改名。他们可能会在短期内失去一些客户。（这可能主要是由于出于某种原因没有意识到名称的改变，或者不喜欢改变）。然而从长远来看，品牌简化将帮助他们脱颖而出。</p><p>我唯一要提到的负面说明是，这是他们在该应用历史上的第三次改名。在 2016 年发布时，它最初被命名为 Vector。当年晚些时候改名为 Riot。希望 Element 能一直用下去。</p><hr>',15)),o("p",null,[t[10]||(t[10]=e("via: ",-1)),n(l,{href:"https://itsfoss.com/riot-to-element/"},{default:i(()=>[...t[9]||(t[9]=[e("https://itsfoss.com/riot-to-element/",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("作者：",-1)),n(l,{href:"https://itsfoss.com/author/john/"},{default:i(()=>[...t[11]||(t[11]=[e("John Paul",-1)])]),_:1}),t[16]||(t[16]=e(" 选题：",-1)),n(l,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[12]||(t[12]=[e("lujun9972",-1)])]),_:1}),t[17]||(t[17]=e(" 译者：",-1)),n(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1}),t[18]||(t[18]=e(" 校对：",-1)),n(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[21]||(t[21]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原创编译，",-1)),n(l,{href:"https://linux.cn/"},{default:i(()=>[...t[20]||(t[20]=[e("Linux中国",-1)])]),_:1}),t[23]||(t[23]=e(" 荣誉推出",-1))])])}const C=s(d,[["render",u]]);export{w as __pageData,C as default};
